codeExamples.code:
-- See available versions, timestamps, and operations
DESCRIBE HISTORY sales.orders;

-- Read the table exactly as of commit version 7
SELECT * FROM sales.orders VERSION AS OF 7;

-- Read the table as of a point in time (resolves to latest version <= that time)
SELECT * FROM sales.orders TIMESTAMP AS OF '2026-06-18 12:00:00';

-- Compare a metric across two versions to spot a bad load
SELECT (SELECT COUNT(*) FROM sales.orders VERSION AS OF 7) AS rows_v7,
       (SELECT COUNT(*) FROM sales.orders VERSION AS OF 8) AS rows_v8;

-- A bad overwrite landed at version 8; roll back to the last good version
RESTORE TABLE sales.orders TO VERSION AS OF 7;
-- Equivalent by time:
-- RESTORE TABLE sales.orders TO TIMESTAMP AS OF '2026-06-18 12:00:00';

-- RESTORE creates a NEW version (e.g., 11) that re-establishes version 7's data;
-- versions 8-10 remain in the log and are still time-travelable while their files exist.

-- Reclaim storage but keep at least 7 days of history (default retention)
VACUUM sales.orders;                 -- uses default 7-day (168h) retention
VACUUM sales.orders RETAIN 168 HOURS;-- explicit
-- After VACUUM, versions whose files fall outside retention can no longer be read.
